<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationEmailVO;

trait UserInvitationEmailAttributeHolder
{
    protected UserInvitationEmailVO|string|null $email = null;
    protected bool $emailAssigned = false;

    public function getEmailOrCurrent(UserInvitationEmailVO $email): UserInvitationEmailVO
    {
        if ($this->emailAssigned) {
            \assert(null !== $this->email);
            return UserInvitationEmailVO::from($this->email);
        } else {
            return $email;
        }
    }
    public function emailTryBuildInitial(ConstraintFailList $error): ?UserInvitationEmailVO
    {
        return  UserInvitationEmailVO::tryFrom($this->emailAssigned ? $this->email : null, $error);
    }
    public function email(UserInvitationEmailVO|string $email): static
    {
        $this->email = $email;
        $this->emailAssigned = true;
        return $this;
    }
    public function getEmail(): ?string
    {
        return $this->email instanceof UserInvitationEmailVO ? $this->email->value() : $this->email;
    }
    public function isEmailAssigned(): bool
    {
        return $this->emailAssigned;
    }
    public function writeEmailTo(mixed $att): void
    {
        if ($this->emailAssigned) {
            \assert(null !== $this->email);
            $att->email($this->email);
        }
    }
    public function readEmailFrom(mixed $att): void
    {
        if ($att->isEmailAssigned()) {
            $email = $att->getEmail();
            \assert(null !== $email);
            $this->email($email);
        }
    }
    public function unsetEmail(): static
    {
        $this->emailAssigned = false;
        return $this;
    }
    protected function withDefaultEmail(): void
    {
    }
    protected function withAssertedEmailRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->emailAssigned = $this->emailAssigned) {
            $value->email = UserInvitationEmailVO::tryFrom($this->email, $errorsList);
        }
    }
}
